CREATE FUNCTION public.update_listings_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE listings
    SET last_seen = NOW()
    WHERE listings.id = NEW.listing_id;
    RETURN NEW;
END;
$$;


